package com.travbook.holidays.adapter.out.supplier;
import com.travbook.holidays.application.port.out.HolidaySupplier;
import com.travbook.holidays.domain.model.Holiday;
import com.travbook.holidays.domain.model.Holiday.*;
import com.travbook.shared.adapter.out.supplier.BoundedDiscovery;
import com.travbook.shared.domain.*;
import java.time.*;
import java.util.*;
public final class MockHolidaySupplier implements HolidaySupplier{
 private final BoundedDiscovery calls;public MockHolidaySupplier(BoundedDiscovery calls){this.calls=calls;}
 public Inventory catalog(String destination,Instant now){var batch=calls.collect("holiday",List.of("sample-atlas","sample-roam"),p->{if(destination.equalsIgnoreCase("Shimla")||p.equals("sample-roam")&&destination.equalsIgnoreCase("Goa"))throw new IllegalStateException("Simulated holiday outage");return packages(p,now).stream().filter(v->destination.isBlank()||v.destination().toLowerCase(Locale.ROOT).contains(destination.strip().toLowerCase(Locale.ROOT))).toList();});return new Inventory(batch.items(),batch.coverage());}
 public Holiday.Package detail(String id,Instant now){String provider=id.startsWith("sample-bali")?"sample-roam":"sample-atlas";return calls.one("holiday",provider,()->packages(provider,now).stream().filter(p->p.id().equals(id)).findFirst().orElseThrow(()->new DomainFailure(DomainFailure.Code.NOT_FOUND,"Holiday package not found.")));}
 private List<Holiday.Package> packages(String supplier,Instant now){return supplier.equals("sample-atlas")?List.of(pack("sample-goa-coast",supplier,"Goa coast, at your pace","Goa",Region.DOMESTIC,Theme.BEACH,3,12000,true,Fulfilment.ENQUIRY,now),pack("sample-jaipur-culture",supplier,"A Jaipur story","Jaipur",Region.DOMESTIC,Theme.CULTURE,2,9000,false,Fulfilment.DIRECT,now)):List.of(pack("sample-bali-island",supplier,"Bali island pause","Bali",Region.INTERNATIONAL,Theme.NATURE,4,32000,false,Fulfilment.ENQUIRY,now));}
 private Holiday.Package pack(String id,String supplier,String title,String destination,Region region,Theme theme,int nights,int base,boolean customization,Fulfilment mode,Instant now){String zone=region==Region.INTERNATIONAL?"Asia/Makassar":"Asia/Kolkata";var day=LocalDate.ofInstant(now,ZoneId.of(zone)).plusDays(2);while(day.getDayOfWeek()!=DayOfWeek.SATURDAY)day=day.plusDays(1);var departures=new ArrayList<LocalDate>();for(int i=0;i<8;i++)departures.add(day.plusWeeks(i));var itinerary=new ArrayList<Day>();for(int i=1;i<=nights+1;i++)itinerary.add(new Day(i,i==1?"Arrive and settle in":i==nights+1?"A slow morning, then departure":"Explore "+destination,"A fictional "+destination+" itinerary with flexible sightseeing time. Activities and accommodation are simulated.",i<=nights?"Sample Garden Stay — standard room":"No overnight stay",i==1?List.of("Dinner"):List.of("Breakfast"),i==1||i==nights+1?"Shared sample arrival/departure transfer":"Shared sample sightseeing transfer"));return new Holiday.Package(id,supplier,title,destination,region,theme,nights,nights+1,(theme==Theme.CULTURE?"/journeys/culture.svg":theme==Theme.NATURE?"/journeys/nature.svg":"/journeys/escape.svg"),"An independent sample itinerary with transparent inclusions, designed for planning only.",List.of("Small-group sample itinerary","Time for independent exploring","Clear included services"),itinerary,List.of(nights+" nights in a sample standard hotel","Listed meals","Shared transfers and sightseeing"),List.of("Flights and visa services","Travel insurance and personal expenses","Unlisted meals or activities"),departures,TravelMoney.inr(base),customization,mode,"MOCK planning policy: enquiries do not incur charges. Booking cancellation/refund terms require supplier confirmation before a real reservation.","MOCK quote includes synthetic 10% tax and INR 200 fee. No payment is collected by this planning quote. Review final booking terms for available payment options.","Pricing only: age 12+ uses adult fare; ages 0–4 use 25%, ages 5–11 use 60%. Traveller and document eligibility must be verified before real fulfilment. COMFORT adds INR 750/person/night; extra activity adds INR 1,200/person.",zone);}
}
